{
 "app_name": "file_system",
 "api_name": "create_directory",
 "path": "/file_system/directory",
 "method": "POST",
 "description": "Create a directory if it does not exist, optionally recursively.",
 "parameters": [
  {
   "name": "directory_path",
   "type": "string",
   "required": true,
   "description": "Path of the directory. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from file_system app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "recursive",
   "type": "boolean",
   "required": false,
   "description": "If True, it will create all parent directories recursively if they don't exist.",
   "default": false,
   "constraints": []
  },
  {
   "name": "allow_if_exists",
   "type": "boolean",
   "required": false,
   "description": "If True, it will not raise an error if the directory already exists.",
   "default": true,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "file_system",
 "api_name": "move_file",
 "path": "/file_system/file/move",
 "method": "POST",
 "description": "Move a file to another location.",
 "parameters": [
  {
   "name": "source_file_path",
   "type": "string",
   "required": true,
   "description": "Path of the source file. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": null,
   "constraints": []
  },
  {
   "name": "destination_file_path",
   "type": "string",
   "required": true,
   "description": "Path of the destination file. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from file_system app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "overwrite",
   "type": "boolean",
   "required": false,
   "description": "Whether to overwrite the file if it already exists.",
   "default": false,
   "constraints": []
  },
  {
   "name": "retain_dates",
   "type": "boolean",
   "required": false,
   "description": "Whether the moved file should retain the original file's created and updated dates.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "destination_file_path": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

